const D = { scale:1, energy:.75, hue:110, speed:1, density:.5, chub:.5, ears:.6, fangs:.6, x:.5, y:.62, seed:0, pose:'auto', style:'etching', act:'prowl' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const u = Math.min(width, height);
const s = u * 0.0030 * P.scale;
const bt = K.beat * P.speed;
const sb = ((bt%1)+1)%1;
const am = .85 + .2*Math.sin(K.t*.31 + fr(6)*6);
const eAmp = P.energy * (.5 + .6*K.intensity) * am;
const kick = Math.min(1.4, K.pulse*(.5+.5*K.intensity) + A.bass*.7);
S.rms = (S.rms||0)*.85 + (A.rms||0)*.15;
S.tre = (S.tre||0)*.8 + (A.treble||0)*.2;
if (S.seedUsed !== P.seed) S.seedUsed = P.seed;

const ACTS = {
  prowl:  ['idle','skitter','snarl','lurk','skitter','idle','snarl','skitter'],
  mayhem: ['skitter','skitter','snarl','skitter','snarl','skitter','snarl','skitter'],
  creep:  ['lurk','idle','lurk','snarl','lurk','idle','lurk','snarl'] };
let pose = P.pose;
if (pose === 'auto') pose = (ACTS[P.act] || ACTS.prowl)[((K.section%8)+8)%8];

const blink = ((K.t*.23 + fr(9))%1) < .06;
const snap = sb < .25 ? sb/.25 : 1;

let dx=0, dy=0, tilt=0, aL=-.4, aR=.4, lsc=1, crouch=1, earA=0, mouth=.15, brow=.3, flash=0;

if (pose === 'idle') {
  dy = Math.sin(K.t*1.6)*4 + K.swell*3*eAmp;
  dx = Math.sin(K.t*.5)*8;
  aL = -.4 + Math.sin(K.t*2.1)*.3; aR = .4 - Math.sin(K.t*2.1)*.3;
  earA = Math.sin(K.t*3)*.14;
  tilt = Math.sin(K.t*.4)*.06;
  mouth = .12 + K.swell*.14; brow = .25;
} else if (pose === 'skitter') {
  const m = ((Math.floor(bt/8)%3)+3)%3;
  const hop = Math.abs(Math.sin(sb*Math.PI));
  dy = -hop*20*eAmp - K.pulse*8*eAmp;
  const jit = Math.sin(K.t*17)*.9;
  if (m === 0) {
    aL = Math.sin(bt*Math.PI*2)*1.5*eAmp + jit*.15; aR = Math.sin(bt*Math.PI*2+Math.PI)*1.5*eAmp - jit*.15;
    dx = Math.sin(bt*Math.PI)*15*eAmp;
    tilt = Math.sin(bt*Math.PI)*.16*eAmp;
    earA = Math.sin(bt*Math.PI*2)*.32;
    mouth = .4 + kick*.4;
  } else if (m === 1) {
    dx = Math.sin(bt*Math.PI*.5)*32*eAmp;
    aL = 1.2 + Math.sin(bt*Math.PI*2)*.5; aR = 1.2 + Math.sin(bt*Math.PI*2+1)*.5;
    tilt = Math.sin(bt*Math.PI)*.2*eAmp;
    earA = Math.abs(Math.sin(bt*Math.PI))*.42;
    mouth = .55 + kick*.3;
  } else {
    dy += -kick*10*eAmp;
    tilt = Math.sin(bt*Math.PI)*.32*eAmp;
    aL = -.9 - jit*.2; aR = .9 + jit*.2;
    mouth = .3 + kick*.5;
    earA = Math.sin(bt*Math.PI*4)*.26;
  }
  brow = .5;
} else if (pose === 'snarl') {
  const c4 = ((Math.floor(bt)%4)+4)%4;
  if (c4 < 3) {
    const gg = (c4+sb)/3;
    crouch = 1 - .12*gg; dy = 8*gg; aL = -.95; aR = .95; mouth = .1;
    brow = .4 + .5*gg; tilt = Math.sin(K.t*18)*.03*gg;
  } else {
    const air = Math.sin(sb*Math.PI);
    lsc = 1 + .42*air*Math.max(.4, eAmp);
    dy = -22*air; aL = -1.7*air - .3; aR = 1.7*air + .3;
    mouth = .4 + .6*air; brow = 1; earA = -.32*air; flash = air;
  }
} else {
  const th = K.t*.5*(.4 + P.speed*.6) + fr(3)*6;
  dx = Math.sin(th)*44*(.4 + eAmp*.6);
  dy = 8 + Math.sin(th*2)*5;
  crouch = .9;
  aL = -.3 + Math.sin(th*2)*.22; aR = .3 - Math.sin(th*2)*.22;
  earA = -.2; brow = .6; mouth = .1;
  tilt = Math.sin(th)*.12;
}

// universal slow drift
dx += Math.sin(K.t*.37 + fr(2)*6)*4;
dy += Math.sin(K.t*.49 + fr(4)*6)*3;
tilt += Math.sin(K.t*.21 + fr(8)*6)*.02;

const styles = ['etching','toxic','wireframe','thermal','classic'];
const st = styles.indexOf(P.style) >= 0 ? P.style : 'etching';
const H = ((P.hue%360)+360)%360;
const WIRE = st === 'wireframe';
const w = .8 + P.chub*.5;
const earScale = .7 + P.ears*1.0;
const fang = .5 + P.fangs*1.2;

const THERM = { body:[38,90,88], belly:[52,95,100], head:[32,85,90], ear:[224,80,66], arm:[212,82,72], leg:[236,72,58] };
function skin(region, a){ if(a===undefined)a=100;
  if (WIRE){ noFill(); stroke(H,70,100,90); strokeWeight(1.4*s); return; }
  noStroke();
  if (st==='toxic'){ fill(H,70,15,a); return; }
  if (st==='thermal'){ const m=THERM[region]||[38,90,88]; fill(m[0],m[1],m[2],a); return; }
  if (st==='etching'){ const b=region==='belly'?50:region==='head'?36:region==='ear'?26:32; fill(H,52,b,a); return; }
  const map={ body:[H,68,58], belly:[H,32,82], head:[H,68,60], ear:[H,62,52], arm:[H,68,52], leg:[H,62,44] };
  const c=map[region]||[H,68,58]; fill(c[0],c[1],c[2],a);
}
function edge(){ if(WIRE) return;
  if(st==='etching'){ stroke(H,60,12,88); strokeWeight(1.5*s); }
  else if(st==='classic'){ stroke(H,70,22,88); strokeWeight(2*s); }
  else noStroke();
}

const pump = 1 + S.rms*.5*P.energy;

// ambient spores / sparks
const nM = Math.max(0, Math.floor(P.density*9));
blendMode(ADD); noStroke();
for (let i=0;i<nM;i++){
  const yy = P.y*height + 40*s - ((((K.t*(14+fr(i)*16) + fr(i+5)*150)%150)+150)%150)*s;
  const xx = P.x*width + (fr(i+9)-.5)*160*s + Math.sin(K.t*.7 + i*2.1)*10*s;
  fill(st==='thermal'?50:H, st==='toxic'?90:60, 100, Math.min(50, 8 + 9*K.swell + S.tre*40));
  circle(xx, yy, (2+fr(i+15)*3)*s*(1+S.tre));
}
blendMode(BLEND);

push();
translate(P.x*width + dx*s, P.y*height + dy*s);
rotate(tilt);
scale(lsc*pump, lsc*pump);
scale(w, crouch);

// contact shadow
if (st!=='wireframe'){ noStroke(); fill(0,0,0, st==='thermal'?0:26); ellipse(0, 66*s, 96*s, 18*s); }

// ===== LEGS / FEET =====
skin('leg'); edge();
ellipse(-22*s, 58*s, 26*s, 22*s);
ellipse(22*s, 58*s, 26*s, 22*s);
if (!WIRE){ skin('leg'); noStroke();
  for (let f=-1;f<=1;f+=1){ triangle((-22+f*7)*s,66*s,(-22+f*7-2)*s,74*s,(-22+f*7+3)*s,66*s); triangle((22+f*7)*s,66*s,(22+f*7-2)*s,74*s,(22+f*7+3)*s,66*s); }
}

// ===== ARMS (behind torso) =====
function arm(sx, ang){
  push(); translate(sx*42*s, -6*s); rotate(ang);
  skin('arm'); edge();
  ellipse(0, 24*s, 17*s, 50*s);
  if (!WIRE){ skin('arm'); noStroke();
    for (let c=-1;c<=1;c++) triangle((c*5)*s,46*s,(c*5-3)*s,58*s,(c*5+3)*s,52*s);
  } else { line(0,46*s, -6*s,58*s); line(0,46*s, 6*s,56*s); }
  pop();
}
arm(-1, aL); arm(1, aR);

// ===== TORSO =====
skin('body'); edge();
beginShape();
vertex(-40*s,-18*s);
bezierVertex(-52*s,30*s,-30*s,58*s,0,58*s);
bezierVertex(30*s,58*s,52*s,30*s,40*s,-18*s);
bezierVertex(30*s,-42*s,-30*s,-42*s,-40*s,-18*s);
endShape(CLOSE);
if (!WIRE && st!=='thermal'){ skin('belly'); noStroke(); ellipse(0, 24*s, 48*s, 60*s); }

// ===== HEAD =====
skin('head'); edge();
ellipse(0, -52*s, 78*s, 66*s);

// ears
function ear(side){
  push(); translate(side*30*s, -70*s); rotate(side*(.5+earA));
  skin('ear'); edge();
  triangle(0,0, side*10*earScale*s, -48*earScale*s, side*-18*s, -8*s);
  if (WIRE) line(0,0, side*10*earScale*s, -48*earScale*s);
  else { skin('ear', 70); noStroke(); triangle(0,-4*s, side*6*earScale*s, -34*earScale*s, side*-8*s, -6*s); }
  pop();
}
ear(-1); ear(1);

// ===== ETCHING HATCH =====
if (st==='etching'){
  stroke(H,55,10,40); strokeWeight(1*s);
  for (let i=0;i<9;i++){ const o=(fr(i+40)-.5)*8; line((-34+i*8+o)*s,(-2)*s,(-40+i*8+o)*s,(38)*s); }
  for (let i=0;i<6;i++){ const o=(fr(i+70)-.5)*6; line((-30+i*11+o)*s,(-70)*s,(-34+i*11+o)*s,(-44)*s); }
  noStroke();
}

// ===== WIREFRAME FACET LINES =====
if (WIRE){
  stroke(H,70,100,70); strokeWeight(1*s);
  line(-40*s,-18*s, 40*s,-18*s); line(0,-42*s,0,58*s);
  line(-40*s,-18*s, 0,58*s); line(40*s,-18*s, 0,58*s);
  line(-39*s,-52*s, 39*s,-52*s); line(0,-85*s,0,-19*s);
  noStroke();
}

// ===== FACE =====
// brow ridge
const bl = brow;
if (!WIRE){ stroke(H, st==='toxic'?80:55, st==='etching'?14:24, 90); strokeWeight(3*s);
  line(-28*s,(-64+bl*8)*s, -6*s,(-58+bl*2)*s);
  line(28*s,(-64+bl*8)*s, 6*s,(-58+bl*2)*s);
  noStroke();
}

// eyes (acid yellow, glow on toxic)
const gx = (fr(Math.floor(K.t*.5)+11)-.5)*4*s;
const gy = (fr(Math.floor(K.t*.5)+23)-.5)*3*s;
const eh = blink ? 3 : 20;
if (st==='toxic'){ blendMode(ADD); drawingContext.shadowBlur = 14; drawingContext.shadowColor = 'hsla(55,100%,55%,0.95)'; }
noStroke();
fill(52, WIRE?100:95, WIRE?100:96, 100);
if (WIRE){ circle(-15*s,-54*s,7*s); circle(15*s,-54*s,7*s); }
else { ellipse(-15*s,-54*s,20*s,eh*s); ellipse(15*s,-54*s,20*s,eh*s); }
if (st==='toxic'){ drawingContext.shadowBlur = 0; blendMode(BLEND); }
if (!blink && !WIRE){ fill(0,0,8,100);
  ellipse(-15*s+gx,-54*s+gy, 6*s, Math.max(6,eh*.5)*s);
  ellipse(15*s+gx,-54*s+gy, 6*s, Math.max(6,eh*.5)*s);
}

// snarling maw with fangs
if (!WIRE){
  const mo = Math.max(2, mouth*22);
  noStroke(); fill(st==='thermal'?12:H, st==='thermal'?90:70, st==='toxic'?6:18, 100);
  ellipse(0, -32*s, 44*s, (6+mo)*s);
  // upper fangs
  fill(0,0,100,100);
  const nF = 4;
  for (let i=0;i<nF;i++){ const fx=(-16+i*11)*s; triangle(fx,(-38+3)*s, fx+7*s,(-38+3)*s, fx+3.5*s,(-38+3+ (5+fang*7))*s); }
  // lower fangs on wide open
  if (mouth>.4){ for (let i=0;i<2;i++){ const fx=(-8+i*14)*s; triangle(fx,(-26)*s, fx+6*s,(-26)*s, fx+3*s,(-26-(4+fang*5))*s); } }
} else {
  stroke(H,70,100,80); strokeWeight(1.2*s); noFill();
  const mo=Math.max(3,mouth*20);
  ellipse(0,-32*s,40*s,(6+mo)*s); noStroke();
}

// thermal hot core
if (st==='thermal'){ blendMode(ADD); noStroke();
  fill(0,0,100, 14+kick*10); ellipse(0,10*s,40*s,54*s); ellipse(0,-50*s,44*s,40*s);
  blendMode(BLEND);
}

// toxic rim pulse
if (st==='toxic'){ blendMode(ADD); noStroke();
  fill(H,90,100, 6+kick*10); ellipse(0,-6*s,150*s,190*s);
  blendMode(BLEND);
}

// snarl flash
if (flash>.05){ blendMode(ADD); noStroke(); fill(H,80,100,22*flash); ellipse(0,-20*s,240*s,270*s); blendMode(BLEND); }

pop();
blendMode(BLEND);
